#include "../pso-cuda/kernel_gpu.cu"
#include "../pso-cuda/kernel_cpu.cpp"
#include <vector>
#include <cstring>
std::vector<float>read(const char*n){FILE*f=fopen(n,"rb");if(!f)exit(3);fseek(f,0,SEEK_END);long bytes=ftell(f);rewind(f);std::vector<float>a(bytes/4);fread(a.data(),4,a.size(),f);fclose(f);return a;}
int main(){constexpr int P=30,R=10,Q=P*DIM;auto input=read("study_input_r10_f32.bin"),cpu=read("study_expected_cpu_r10_f32.bin");float *pos,*vel,*best,*global;cudaMalloc(&pos,Q*4);cudaMalloc(&vel,Q*4);cudaMalloc(&best,Q*4);cudaMalloc(&global,DIM*4);auto reset=[&](){cudaMemcpy(pos,input.data(),Q*4,cudaMemcpyHostToDevice);cudaMemcpy(vel,input.data()+Q,Q*4,cudaMemcpyHostToDevice);cudaMemcpy(best,input.data()+2*Q,Q*4,cudaMemcpyHostToDevice);cudaMemcpy(global,input.data()+3*Q,DIM*4,cudaMemcpyHostToDevice);};auto execute=[&](){for(int iter=0;iter<R;iter++){float rp=getRandomClamped(iter),rg=getRandomClamped(R-iter);kernelUpdateParticle<<<4,256>>>(pos,vel,best,global,P,rp,rg);kernelUpdatePBest<<<1,256>>>(pos,best,global,P);}};reset();execute();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;bool all=true;for(int trial=1;trial<=5;trial++){reset();cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();execute();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R;std::vector<float>state(3*Q+DIM);cudaMemcpy(state.data(),pos,Q*4,cudaMemcpyDeviceToHost);cudaMemcpy(state.data()+Q,vel,Q*4,cudaMemcpyDeviceToHost);cudaMemcpy(state.data()+2*Q,best,Q*4,cudaMemcpyDeviceToHost);cudaMemcpy(state.data()+3*Q,global,DIM*4,cudaMemcpyDeviceToHost);bool ok=status==cudaSuccess;double ma=0,mr=0;int failures=0;for(size_t i=0;i<state.size();i++){double d=fabs(double(state[i])-cpu[i]);ma=std::max(ma,d);mr=std::max(mr,d/std::max(fabs(double(cpu[i])),1e-12));ok&=std::isfinite(state[i])&&d<=1e-3;if(d>1e-3)failures++;}all&=ok;std::vector<float>out=input;out.insert(out.end(),{float(P),float(R),OMEGA,c1,c2,phi});out.insert(out.end(),state.begin(),state.end());char name[100];snprintf(name,100,"output_trial%d.bin",trial);FILE*f=fopen(name,"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"state_values_outside_tolerance\":%d,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,mr,failures,R,name,out.size());}return all?0:1;}
